package com.tekwatt.support.service;import com.tekwatt.support.dto.*;import com.tekwatt.support.entity.*;import com.tekwatt.support.repository.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;@Service @Transactional public class MaintenanceService{private final MaintenanceJobRepository jobs;private final AmcContractRepository contracts;public MaintenanceService(MaintenanceJobRepository j,AmcContractRepository c){jobs=j;contracts=c;}public MaintenanceJob create(MaintenanceJobRequest r){return jobs.save(new MaintenanceJob(r.tenantId(),r.title(),r.description(),r.type(),r.stationId(),r.chargerId(),r.technicianId(),r.technicianName(),r.scheduledAt()));}@Transactional(readOnly=true)public List<MaintenanceJob>jobs(UUID t){return jobs.findAllByTenantIdOrderByScheduledAtDesc(t);}public MaintenanceJob jobStatus(UUID id,String s){MaintenanceJob j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Maintenance job not found"));j.status(s.toUpperCase());return j;}public AmcContract create(AmcContractRequest r){if(r.endDate().isBefore(r.startDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End date must follow start date");return contracts.save(new AmcContract(r.tenantId(),r.partnerId(),r.stationId(),r.startDate(),r.endDate(),r.amount(),r.currency().toUpperCase()));}@Transactional(readOnly=true)public List<AmcContract>contracts(UUID t){return contracts.findAllByTenantIdOrderByCreatedAtDesc(t);}public AmcContract contractStatus(UUID id,String s){AmcContract c=contracts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"AMC contract not found"));c.status(s.toUpperCase());return c;}}
